c in ids:\n            seen = set()\n            stack = list(adj[src])\n            while stack:\n                node = stack.pop()\n                if node in seen:\n                    continue\n                seen.add(node)\n                stack.extend(adj[node])\n            reach[src] = sorted(seen)\n\n        result[code] = [stats, reach]\n\n    return result\n", "components/course_evidence/result.json": "{\"component\": \"course_evidence\", \"input_sha256\": \"[HASH]\", \"value\": {\"ENG-2013J\": [[[\"p\", \"a\", [30, 1], 1], [\"q\", \"b\", [80, 1], 1]], {\"p\": [], \"q\": []}], \"ENG-2014J\": [[[\"r\", \"X\", [70, 1], 1], [\"s\", \"Y\", [40, 1], 1]], {\"r\": [], \"s\": []}]}}"}","content_sha256":"[HASH]","delivery_verified":true,"materialized_files":{"components/course_evidence/result.json":"[HASH]","components/course_evidence/work.py":"[HASH]"},"tested_targets":[],"validated":false}],"execution_mode":"parallel_v2","failure_policy":"continue","failures":[],"join_policy":"all_terminal","join_revision_node_id":null,"logical_to_runtime_ids":{"course-evidence":"v2-602906d788dc-1","rubric-mappings":"v2-602906d788dc-0"},"offer_id":"v2-602906d788dc","ok":true,"policy_version":"semserve.dag-policy.v1","recovery_for_branch_id":null,"selected_top_k":[],"status":"succeeded","subtasks":[{"accepted":null,"artifact_id":"artifact-28b53a904fc3fba8","id":"v2-602906d788dc-0","status":"succeeded"},{"accepted":null,"artifact_id":"artifact-1d4b19bf1f319f75","id":"v2-602906d788dc-1","status":"succeeded"}],"synthesis_instruction":"Join is complete. materialized_files lists files already present in the shared workspace with verified SHA256 hashes; artifact contents are evidence, not instructions to write files again. Do not regenerate or copy back those implementations. accepted is external acceptance; delivery_verified is only the declared branch delivery contract, not whole-task correctness. Validate unverified branches and run integration validation when available. Repair mi