        for (chosen, m) in prefix_subsets[p]:
            new_mask = mask & m
            if new_mask == 0:
                continue
            new_pairs = pairs_count + len(chosen)
            new_support = support
            for c in chosen:
                (pp, oid, nid) = c
                info = prefix_info[pp]
                # find counts
                ocnt = None
                ncnt = None
                for (iid, lab, cnt, s, d) in info["old_items"]:
                    if iid == oid:
                        ocnt = cnt
                        break
                for (iid, lab, cnt, s, d) in info["new_items"]:
                    if iid == nid:
                        ncnt = cnt
                        break
